async function piBookingLooksBlocked(page) {
  const text = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ');
  const watch = page && page._piBookingWatch;
  if (watch && (watch.blockedHttp || piBookingBlock.looksBlockedStatus(watch.lastStatus))) return true;
  return piBookingLooksBlockedText(text);
}
function piBookingBlockedHint() {
  return 'Booking.com blocked this sign-in (Try again later). This is not a wrong password — Booking.com blocked this server network. Do not retry now; waiting a minute makes it worse. Leave Collect closed for several hours.';
}
function piBookingCooldownMs() {
  const n = Number(process.env.BOOKING_CONNECT_COOLDOWN_MS);
  return Number.isFinite(n) && n >= 0 ? n : (4 * 60 * 60 * 1000);
}
async function piBookingReadBlockedUntil() {
  const row = await piBookingBlock.readBlocked(pool);
  return row && Number(row.until) > Date.now() ? Number(row.until) : 0;
}
async function piBookingMarkNetworkBlocked(job) {
  const watch = job && job.page && job.page._piBookingWatch;
  const row = await piBookingBlock.markBlocked(pool, {
    source: 'connect',
    status: watch && watch.lastStatus,
    reason: job && job.pageSnippet
  });
  const until = (row && row.until) || (Date.now() + piBookingCooldownMs());
  if (job) {
    job.networkBlocked = true;
    job.cooldownUntil = until;
    job.status = 'blocked';
    job.error = null;
    job.hint = piBookingBlockedHint();
    job.updatedAt = Date.now();
  }
}

